import csv
import io

texto = "producto,unidades\n" + "".join(f"p{i},{i}\n" for i in range(1, 7))
datos = io.StringIO(texto)   # en un caso real: with open("ventas.csv") as datos

def filas(archivo):
    """Convierte cada línea del CSV en una tupla con tipos."""
    for fila in csv.DictReader(archivo):
        yield fila["producto"], int(fila["unidades"])

def mayores(pares, minimo):
    """Deja pasar solo los pares que cumplen el umbral."""
    for nombre, unidades in pares:
        if unidades >= minimo:
            yield nombre, unidades

total = 0
for nombre, unidades in mayores(filas(datos), 4):
    total += unidades
    print(nombre, unidades)

print("Total:", total)

def contar_hasta(n):
    i = 1
    while i <= n:
        yield i
        i += 1

for valor in contar_hasta(2):
    print(valor)

