from itertools import islice

def lecturas(inicio):
    valor = inicio
    while True:
        yield round(valor, 1)
        valor += 1.5

for lectura in islice(lecturas(20.0), 5):
    print(lectura)

ventas = [
    {"producto": "teclado", "sede": "Lima", "unidades": 3, "precio": 120.0},
    {"producto": "mouse", "sede": "Lima", "unidades": 5, "precio": 45.5},
    {"producto": "monitor", "sede": "Cusco", "unidades": 1, "precio": 900.0},
]

def de_sede(registros, sede):
    for registro in registros:
        if registro["sede"] == sede:
            yield registro

def importes(registros):
    for registro in registros:
        yield registro["producto"], round(registro["unidades"] * registro["precio"], 2)

def total(pares):
    suma = 0.0
    for _, monto in pares:
        suma += monto
    return suma

print(list(importes(de_sede(ventas, "Lima"))))
print(total(importes(de_sede(ventas, "Lima"))))

